// Check that no tracked text file has an en or em dash: the site, docs,
// comments and messages use plain hyphens, or are restructured, instead.
// Run by `npm run lint`.
import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = fileURLToPath(new URL('..', import.meta.url));
// En dash (U+2013) and em dash (U+2014), written as escapes so this file
// passes its own check
const DASH = /[\u2013\u2014]/g;
// Generated by npm, and files that aren't text
const GENERATED = /(?:^|\/)package-lock\.json$/;
const BINARY = /\.(?:png|jpe?g|webp|gif|ico|woff2?|ttf|otf|pdf)$/i;
const files = execFileSync('git', ['ls-files', '-z'], {
  cwd: ROOT,
  encoding: 'utf8'
})
  .split('\0')
  .filter((file) => file && !GENERATED.test(file) && !BINARY.test(file));
const problems = [];

for (const file of files) {
  const lines = readFileSync(join(ROOT, file), 'utf8').split('\n');

  lines.forEach((line, index) => {
    if (DASH.test(line)) {
      problems.push(`${file}:${index + 1}  ${line.trim().slice(0, 100)}`);
    }

    DASH.lastIndex = 0;
  });
}

if (problems.length > 0) {
  console.error(
    `${problems.length} line(s) with an en or em dash. Use a hyphen, a colon or a comma, or restructure the sentence:\n\n${problems.join('\n')}`
  );
  process.exit(1);
}

console.log(`No en or em dashes in ${files.length} files`);
